comptime fn make_tuple_eq_body(n: u32) -> Quoted {
    let mut body = f"self.0.eq(other.0)".as_ctstring();
    for i in 1u32..n {
        body = body.append_fmtstr(f" & self.{i}.eq(other.{i})");
    }
    f"{body}".quoted_contents()
}

